### What the interviewer probes
- Narrate: say what state you keep and why before typing.
- Make level 1 simple and correct first; do not pre-build later levels.
- Timestamps are plain ints passed into each method, so behaviour is deterministic.
- Read each level brief twice: return values for the "missing" cases (None / False) are where points are lost.
- Keep one class and grow it; refactor when a level asks for something your first design can't hold.

### Key insight
One dict `path -> (size, owner)` answers every query. Quotas are **derived** (capacity minus owned sizes), so deletes, merges and restores never have to update a counter, and that is where most bugs in this problem come from.

### Reference implementation
```python
class FileSystem:
    ADMIN = "admin"

    def __init__(self) -> None:
        self._files: dict[str, tuple[int, str]] = {}          # path -> (size, owner)
        self._capacity: dict[str, int | None] = {self.ADMIN: None}  # None = unlimited
        self._backups: dict[str, dict[str, int]] = {}         # user -> {path: size}

    @staticmethod
    def _check(path: str, size: int) -> None:
        if not isinstance(path, str) or not path.startswith("/"):
            raise ValueError("path must start with '/'")
        if size < 0:
            raise ValueError("size must be >= 0")

    # ---- level 1
    def add_file(self, path: str, size: int) -> bool:
        self._check(path, size)
        if path in self._files:
            return False
        self._files[path] = (size, self.ADMIN)
        return True

    def get_file_size(self, path: str) -> int | None:
        entry = self._files.get(path)
        return None if entry is None else entry[0]

    def delete_file(self, path: str) -> int | None:
        entry = self._files.pop(path, None)
        return None if entry is None else entry[0]

    # ---- level 2
    def largest_files(self, prefix: str, n: int) -> list[str]:
        if n <= 0:
            return []
        matches = [(size, path) for path, (size, _) in self._files.items() if path.startswith(prefix)]
        matches.sort(key=lambda item: (-item[0], item[1]))
        return [f"{path}({size})" for size, path in matches[:n]]

    def total_size(self, prefix: str) -> int:
        return sum(size for path, (size, _) in self._files.items() if path.startswith(prefix))
```

```python
    # ---- level 3 (methods of FileSystem, continued)
    def _used(self, user_id: str) -> int:
        return sum(size for size, owner in self._files.values() if owner == user_id)

    def add_user(self, user_id: str, capacity: int) -> bool:
        if capacity < 0:
            raise ValueError("capacity must be >= 0")
        if user_id in self._capacity:
            return False
        self._capacity[user_id] = capacity
        return True

    def remaining_capacity(self, user_id: str) -> int | None:
        capacity = self._capacity.get(user_id)
        if capacity is None:  # unknown user, or admin (unlimited)
            return None
        return capacity - self._used(user_id)

    def add_file_by(self, user_id: str, path: str, size: int) -> int | None:
        self._check(path, size)
        if user_id not in self._capacity or path in self._files:
            return None
        if user_id == self.ADMIN:
            self._files[path] = (size, user_id)
            return None
        remaining = self.remaining_capacity(user_id)
        if size > remaining:
            return None
        self._files[path] = (size, user_id)
        return remaining - size

    def merge_users(self, user_id_1: str, user_id_2: str) -> int | None:
        if user_id_1 == user_id_2 or self.ADMIN in (user_id_1, user_id_2):
            return None
        if user_id_1 not in self._capacity or user_id_2 not in self._capacity:
            return None
        self._capacity[user_id_1] += self._capacity.pop(user_id_2)
        for path, (size, owner) in list(self._files.items()):
            if owner == user_id_2:
                self._files[path] = (size, user_id_1)
        self._backups.pop(user_id_2, None)
        return self.remaining_capacity(user_id_1)

    # ---- level 4
    def backup_user(self, user_id: str) -> int | None:
        if user_id not in self._capacity:
            return None
        snapshot = {path: size for path, (size, owner) in self._files.items() if owner == user_id}
        self._backups[user_id] = snapshot
        return len(snapshot)

    def restore_user(self, user_id: str) -> int | None:
        if user_id not in self._capacity:
            return None
        for path in [p for p, (_, owner) in self._files.items() if owner == user_id]:
            del self._files[path]
        restored = 0
        for path, size in sorted(self._backups.get(user_id, {}).items()):
            if path not in self._files:  # taken by someone else meanwhile: skip
                self._files[path] = (size, user_id)
                restored += 1
        return restored
```

### Design notes per level
- **Level 1:** validate before mutating; the admin owner is set even though level 1 doesn't need it yet (cheap to plan for).
- **Level 2:** filter by `startswith`, sort by `(-size, path)`. O(n log n) per query; mention a sorted structure or per-directory aggregates if they push on scale.
- **Level 3:** capacity dict with `None` for admin; `_used` is O(n), fine at interview scale; a per-user running total is the optimisation once correctness is proven.
- **Level 4:** a backup is an independent dict copy. Restore = delete current files, re-add free paths. Merge drops user 2's backup.

### Common pitfalls
- Checking `size > capacity` instead of `size > remaining`.
- A running "used" counter that is not updated by `delete_file` or merges.
- `restore_user` overwriting a path another user now owns.
- Returning `None` instead of `0` when the user has no backup.
- Letting `"admin"` be merged or treated as an unknown user.

