        raise NotImplementedError

    def peek(self, timestamp: int) -> str | None:
        """The task pop() would return, without removing it."""
        raise NotImplementedError

    def pop(self, timestamp: int) -> str | None:
        """Start the highest-priority task (ties: added first); None if none."""
        raise NotImplementedError

    def complete(self, timestamp: int, task_id: str) -> bool:
        """Mark a running task done."""
        raise NotImplementedError

    def cancel(self, timestamp: int, task_id: str) -> bool:
